@prefix sh:   <http://www.w3.org/ns/shacl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix qudt: <http://qudt.org/schema/qudt/> .
@prefix vocab: <https://w3id.org/nltl/vocab#> .
@prefix ex:   <https://example.org/shapes#> .
@prefix unit: <http://qudt.org/vocab/unit/> .

# -----------------------------------------------------------------
# Shape that validates any QUDT QuantityValue used for rule lengths
# -----------------------------------------------------------------
ex:QuantityShape
    a sh:NodeShape ;
    sh:targetObjectsOf vocab:classificationSocietyRuleLength , vocab:ruleLength ;

    # The quantity must have a numeric value (decimal)
    sh:property [
        sh:path qudt:numericValue ;
        sh:datatype xsd:decimal ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
    ] ;

    # The quantity must be expressed in metres
    sh:property [
        sh:path qudt:unit ;
        sh:hasValue unit:M ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
    ] .

# -----------------------------------------------------------------
# Ship shape – enforces presence of the required length quantities
# -----------------------------------------------------------------
ex:ShipShape
    a sh:NodeShape ;
    sh:targetClass vocab:ship ;

    # L (the rule length used by the classification society) must be present
    sh:property [
        sh:path vocab:classificationSocietyRuleLength ;
        sh:minCount 1 ;
        sh:node ex:QuantityShape ;
    ] ;

    # The generic ruleLength property must also be present and must be the same
    # quantity as the classificationSocietyRuleLength (L = ruleLength)
    sh:property [
        sh:path vocab:ruleLength ;
        sh:minCount 1 ;
        sh:node ex:QuantityShape ;
        sh:equals vocab:classificationSocietyRuleLength ;
    ] .

